<script setup lang="ts">import { computed } from 'vue'; import { NDrawer, NDrawerContent, NDescriptions, NDescriptionsItem, NTag } from 'naive-ui'; import { useCompetitionTraceStore } from '@/stores/hermes/competition-trace'; const trace=useCompetitionTraceStore(); const visible=computed(()=>!!trace.selectedTraceId); function close(){trace.selectedTraceId=null}</script>
<template><NDrawer :show="visible" :width="360" placement="right" @update:show="value => { if (!value) close() }"><NDrawerContent title="追踪详情"><template v-if="trace.selectedTrace"><NTag>{{ trace.selectedTrace.status }}</NTag><NDescriptions label-placement="left" :column="1" bordered><NDescriptionsItem label="追踪 ID">{{ trace.selectedTrace.traceId }}</NDescriptionsItem><NDescriptionsItem label="智能体">{{ trace.selectedTrace.agent }}</NDescriptionsItem><NDescriptionsItem label="模型">{{ trace.selectedTrace.model || '-' }}</NDescriptionsItem><NDescriptionsItem label="阶段">{{ trace.selectedTrace.phase || '-' }}</NDescriptionsItem><NDescriptionsItem label="Tokens">{{ trace.selectedTrace.tokens ?? '-' }}</NDescriptionsItem><NDescriptionsItem label="费用">{{ trace.selectedTrace.cost ?? '-' }}</NDescriptionsItem></NDescriptions></template></NDrawerContent></NDrawer></template>
